			readonly QueryProperty: PersistenceRequestType,
			readonly QueryEntities: PersistenceRequestType,
			readonly ManipulationRequest: PersistenceRequestType,
			readonly ReferencesRequest: PersistenceRequestType,
			readonly GetPartitions: PersistenceRequestType,
			readonly GetModel: PersistenceRequestType,
			readonly Custom: PersistenceRequestType,
